const input = $json || {};

const value =
  input.entry?.[0]?.changes?.[0]?.value ||
  input.value ||
  input.body?.entry?.[0]?.changes?.[0]?.value ||
  input;

const message = value.messages?.[0] || input.messages?.[0] || null;
const status = value.statuses?.[0] || input.statuses?.[0] || null;
const contact = value.contacts?.[0] || {};

// Ignore delivery/read/status webhook events.
// We only want actual customer messages.
if (!message) {
  return [];
}

let text = "";

if (message.type === "text") {
  text = message.text?.body || "";
}

if (message.type === "button") {
  text = message.button?.text || message.button?.payload || "";
}

if (message.type === "interactive") {
  text =
    message.interactive?.button_reply?.title ||
    message.interactive?.button_reply?.id ||
    message.interactive?.list_reply?.title ||
    message.interactive?.list_reply?.id ||
    "";
}

const media = {
  has_media: ["image", "document", "audio", "video"].includes(message.type),
  type: message.type || "text",
  id:
    message.image?.id ||
    message.document?.id ||
    message.audio?.id ||
    message.video?.id ||
    "",
  mime_type:
    message.image?.mime_type ||
    message.document?.mime_type ||
    message.audio?.mime_type ||
    message.video?.mime_type ||
    "",
  filename: message.document?.filename || "",
  caption: message.image?.caption || message.document?.caption || ""
};

// IMPORTANT:
// message.from is the CUSTOMER WhatsApp number.
// value.metadata.display_phone_number / phone_number_id is your business/test number.
// So customer_id must always come from message.from.
const customerPhone = message.from || contact.wa_id || "";

return [
  {
    json: {
      source: "whatsapp",
      channel: "whatsapp",
      customer_id: customerPhone,
      whatsapp_phone: customerPhone,
      customer_name: contact.profile?.name || "",
      message: text || media.caption || "",
      message_type: message.type || "text",
      media,
      whatsapp_message_id: message.id || "",
      whatsapp_timestamp: message.timestamp || "",
      business_phone_number_id: value.metadata?.phone_number_id || "",
      business_display_phone_number: value.metadata?.display_phone_number || "",
      raw_whatsapp_payload: input,
      received_at: new Date().toISOString()
    }
  }
];

const incoming = $('CODE_Normalize_WhatsApp_Input').first().json || {};
const row = $json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(raw); } catch (e) { return {}; }
}

let data = parseSession(row.session_data);
const msgRaw = String(incoming.message || '').trim();
const msg = msgRaw.toLowerCase();

let language = row.language || data.language || '';
let currentStage = row.current_stage || data.current_stage || 'language_selection';
let activeService = row.active_service || data.active_service || '';
let reply = '';
let shouldCallMarriage = false;
let route = 'direct_reply';

function menuByLanguage(lang) {
  if (lang === 'Tamil') {
    return 'தயவு செய்து ஒரு விருப்பத்தைத் தேர்வு செய்யவும்:\n\n1️⃣ சேவை கோரிக்கை நிலை\n2️⃣ புதிய சேவை கோரிக்கை\n\nஎண்ணை மட்டும் பதிலளிக்கவும்.';
  }
  if (lang === 'Tanglish') {
    return 'Please unga option choose pannunga:\n\n1️⃣ Service Request Status\n2️⃣ New Service Request\n\nOption number mattum reply pannunga.';
  }
  return 'Please choose an option:\n\n1️⃣ Service Request Status\n2️⃣ Requesting for New Service\n\nReply with the option number.';
}

function serviceMenuByLanguage(lang) {
  if (lang === 'Tamil') return 'தயவு செய்து சேவையைத் தேர்வு செய்யவும்:\n\n1️⃣ திருமண பதிவு\n\nஎண்ணை மட்டும் பதிலளிக்கவும்.';
  if (lang === 'Tanglish') return 'Please unga service choose pannunga:\n\n1️⃣ Marriage Registration\n\nOption number mattum reply pannunga.';
  return 'Please select the service you need:\n\n1️⃣ Marriage Registration\n\nReply with the option number.';
}

function languageMenu() {
  return 'Welcome to LANDOC Services.\n\nPlease choose your preferred language:\n\n1️⃣ English\n2️⃣ தமிழ்\n3️⃣ Tanglish';
}

// Global commands
if (['restart','reset','start'].includes(msg)) {
  data = {};
  language = '';
  activeService = '';
  currentStage = 'language_selection';
}
if (['menu','main menu'].includes(msg)) {
  activeService = '';
  currentStage = 'main_menu';
  data.active_service = '';
  data.current_stage = 'main_menu';
  reply = menuByLanguage(language || data.language || 'English');
}
if (msg.includes('change language') || msg === 'language') {
  activeService = '';
  language = '';
  currentStage = 'language_selection';
  data.active_service = '';
  data.current_stage = 'language_selection';
  data.language = '';
  reply = languageMenu();
}

// First-time or language selection
if (!reply && currentStage === 'language_selection') {
  if (msg === '1') language = 'English';
  else if (msg === '2') language = 'Tamil';
  else if (msg === '3') language = 'Tanglish';
  else {
    reply = languageMenu();
    data.current_stage = 'language_selection';
    data.active_service = '';
  }

  if (!reply) {
    data.language = language;
    data.current_stage = 'main_menu';
    data.active_service = '';
    activeService = '';
    currentStage = 'main_menu';
    reply = menuByLanguage(language);
  }
}

// Main menu
if (!reply && currentStage === 'main_menu') {
  if (msg === '1') {
    data.main_menu_selected = 'service_status';
    data.current_stage = 'ticket_status_reference';
    data.active_service = '';
    activeService = '';
    currentStage = 'ticket_status_reference';
    reply = language === 'Tamil'
      ? 'உங்கள் சேவை கோரிக்கை எண் அல்லது பதிவு செய்யப்பட்ட மொபைல் எண்ணை பகிரவும்.'
      : language === 'Tanglish'
        ? 'Unga service request number illa registered mobile number share pannunga.'
        : 'Please share your service request number or registered mobile number to check the status.';
  } else if (msg === '2') {
    data.main_menu_selected = 'new_service';
    data.current_stage = 'service_selection';
    data.active_service = '';
    activeService = '';
    currentStage = 'service_selection';
    reply = serviceMenuByLanguage(language || data.language || 'English');
  } else {
    reply = menuByLanguage(language || data.language || 'English');
  }
}

// Service selection
if (!reply && currentStage === 'service_selection') {
  if (msg === '1' || msg.includes('marriage')) {
    data.main_menu_selected = 'new_service';
    data.active_service = 'marriage_registration';
    data.intent = 'marriage_registration';
    data.current_stage = 'start';
    data.language = language || data.language || 'English';
    activeService = 'marriage_registration';
    currentStage = 'start';
    shouldCallMarriage = true;
    route = 'marriage_service';
  } else {
    reply = serviceMenuByLanguage(language || data.language || 'English');
  }
}

// Ticket status placeholder. Add Odoo status GET later.
if (!reply && currentStage === 'ticket_status_reference') {
  data.ticket_status_requested = true;
  data.ticket_reference = msgRaw;
  data.current_stage = 'main_menu';
  reply = language === 'Tamil'
    ? 'நன்றி. உங்கள் சேவை நிலையை சரிபார்க்க எங்கள் குழு உதவும். முக்கிய மெனுவுக்கு திரும்புகிறோம்.\n\n' + menuByLanguage(language)
    : language === 'Tanglish'
      ? 'Nandri. Unga service status check panna team help pannuvanga. Main menu ku thirumbi porom.\n\n' + menuByLanguage(language)
      : 'Thank you. Our team will help check your service status. Returning to main menu.\n\n' + menuByLanguage(language);
}

// Existing active marriage service path
if (!reply && activeService === 'marriage_registration') {
  shouldCallMarriage = true;
  route = 'marriage_service';
}

// Fallback
if (!reply && !shouldCallMarriage) {
  reply = languageMenu();
  currentStage = 'language_selection';
  activeService = '';
  data.current_stage = 'language_selection';
  data.active_service = '';
}

data.language = language || data.language || '';
data.current_stage = currentStage;
data.active_service = activeService;

data.whatsapp_phone = incoming.whatsapp_phone;
data.customer_name = incoming.customer_name || data.customer_name || '';

return [{
  json: {
    customer_id: incoming.customer_id,
    channel: 'whatsapp',
    whatsapp_phone: incoming.whatsapp_phone,
    customer_name: incoming.customer_name,
