function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(raw); } catch (e) { return {}; }
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'uploaded_document';
}

function getLabel(item) {
  if (!item) return '';
  if (typeof item === 'string') return item;
  return item.label || item.name || item.document_name || item.description || item.title || item.required_document || '';
}

function getCode(item) {
  if (!item) return '';
  if (typeof item === 'string') return slugify(item);
  return item.code || item.description_code || item.key || item.document_code || slugify(getLabel(item));
}

function isUploaded(item, uploadedCodes, uploadedLabels) {
  const code = getCode(item);
  const label = getLabel(item);
  if (code && uploadedCodes.has(code)) return true;
  if (label && uploadedLabels.has(label.toLowerCase())) return true;
  if (typeof item === 'object') {
    const status = String(item.status || item.upload_status || item.state || '').toLowerCase();
    if (item.uploaded === true || item.is_uploaded === true || ['uploaded', 'received', 'done'].includes(status)) return true;
  }
  return false;
}

function extractExpectedFromReply(text) {
  const s = String(text || '');
  const patterns = [
    /First document required:\s*([^\n\r]+)/i,
    /Please upload:\s*([^\n\r]+)/i,
    /Please upload the required document:\s*([^\n\r]+)/i,
    /upload:\s*([^\n\r]+)/i
  ];
  for (const p of patterns) {
    const m = s.match(p);
    if (m && m[1]) return m[1].trim();
  }
  return '';
}

