function deepFind(obj, keys) {
  if (!obj || typeof obj !== 'object') return '';

  for (const key of keys) {
    if (
      Object.prototype.hasOwnProperty.call(obj, key) &&
      obj[key] !== undefined &&
      obj[key] !== null &&
      String(obj[key]).trim() !== ''
    ) {
      return obj[key];
    }
  }

  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const found = deepFind(value, keys);
      if (found !== '') return found;
    }
  }

  return '';
}

function deepFindObjectWithKeys(obj, keys) {
  if (!obj || typeof obj !== 'object') return null;

  const hasAnyKey = keys.some((key) =>
    Object.prototype.hasOwnProperty.call(obj, key) &&
    obj[key] !== undefined &&
    obj[key] !== null &&
    String(obj[key]).trim() !== ''
  );

  if (hasAnyKey) return obj;

  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const found = deepFindObjectWithKeys(value, keys);
      if (found) return found;
    }
  }

  return null;
}

function findRequestNumberFromText(...texts) {
  const combined = texts
    .filter(Boolean)
    .map(v => {
      if (typeof v === 'object') {
        try {
          return JSON.stringify(v);
        } catch (e) {
          return '';
        }
      }
      return String(v);
    })
    .join('\n');

  const match = combined.match(/\bL\d{3,}\b/i);
  return match ? match[0].toUpperCase() : '';
}

function validRequestNumber(value) {
  return /^L\d{3,}$/i.test(String(value || '').trim());
}

function normalizeServiceCode(value) {
  const v = String(value || '').trim().toLowerCase();

  if (!v) return '';

  const map = {
    'hindu marriage': 'hindu_marriage',
    'hindu marriage certificate': 'hindu_marriage',
    'muslim marriage': 'muslim_marriage',
    'christian marriage': 'christian_marriage',
    'special marriage': 'special_marriage',
    'tamilnadu marriage': 'tamilnadu_marriage',
    'tamil nadu marriage': 'tamilnadu_marriage',
    'both together': 'hindu_and_tamilnadu_marriage',
    'hindu + tamilnadu marriage': 'hindu_and_tamilnadu_marriage'
  };

  if (map[v]) return map[v];

  return v.replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function normalizeDescriptionCode(value) {
  const v = String(value || '').trim();

  if (!v) return '';

  const lower = v.toLowerCase();

  // These are requirement types / placeholders, not checklist line description_code.
  const invalidAsDescriptionCode = [
    'required_document',
    'optional_document',
    'required',
    'optional',
    'document',
    'file',
    'upload',
    'attachment'
  ];

  if (invalidAsDescriptionCode.includes(lower)) return '';

  return lower.replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function normalizeRequirementType(value) {
  const v = String(value || '').trim().toLowerCase();

  if (
    v === 'required_document' ||
    v === 'required' ||
    v === 'mandatory' ||
    v === 'yes' ||
    v === 'true'
  ) {
    return 'required_document';
  }

  if (
    v === 'optional_document' ||
    v === 'optional' ||
    v === 'no' ||
    v === 'false'
  ) {
    return 'optional_document';
  }

  return '';
}

function toBool(value) {
  const v = String(value || '').trim().toLowerCase();
  return value === true || ['true', 'yes', '1', 'required', 'mandatory', 'required_document'].includes(v);
}

function getDocumentLabelFromCode(code) {
  const value = String(code || '').trim();

  if (!value) return 'the document';

  return value
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

