  return [];
}

function updateDocInList(list, uploadedCode, updateValues) {
  if (!Array.isArray(list)) return list;

  return list.map((doc) => {
    if (getDocCode(doc) === uploadedCode) {
      return {
        ...doc,
        ...updateValues
      };
    }

    return doc;
  });
}

function updateDocInSession(data, code, updateValues) {
  data.document_checklist = updateDocInList(data.document_checklist, code, updateValues);
  data.required_documents = updateDocInList(data.required_documents, code, updateValues);
  data.pending_required_documents = updateDocInList(data.pending_required_documents, code, updateValues);
}

