function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || '';
}

function firstNonEmpty(...values) {
  for (const v of values) {
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return v;
    }
  }
  return '';
}

function boolValue(value) {
  const v = String(value || '').trim().toLowerCase();
  return (
    value === true ||
    value === 1 ||
    v === 'true' ||
    v === 'yes' ||
    v === '1' ||
    v === 'required' ||
    v === 'mandatory' ||
    v === 'required_document'
  );
}

function normalizeRequirementType(value) {
  const v = String(value || '').trim().toLowerCase();

  if (
    v === 'required_document' ||
    v === 'required' ||
    v === 'mandatory' ||
    v === 'true' ||
    v === 'yes' ||
    v === '1'
  ) {
    return 'required_document';
  }

  if (
    v === 'optional_document' ||
    v === 'optional' ||
    v === 'false' ||
    v === 'no' ||
    v === '0'
  ) {
    return 'optional_document';
  }

  return '';
}

function isInvalidDescriptionCode(value) {
  const v = String(value || '').trim().toLowerCase();

  return [
    '',
    'required',
    'optional',
    'required_document',
    'optional_document',
    'document',
    'file',
    'upload',
    'attachment',
    'uploaded_document'
  ].includes(v);
}

function normalizeDescriptionCode(value) {
  const code = slugify(value);
  return isInvalidDescriptionCode(code) ? '' : code;
}

function getLabel(item) {
  if (!item) return '';
  if (typeof item === 'string') return item;

  return firstNonEmpty(
    item.label,
    item.name,
    item.document_name,
    item.description,
    item.title,
    item.required_document,
    item.document_label,
    item.checklist,
    item.checklist_name
  );
}

function getCode(item) {
  if (!item) return '';

  if (typeof item === 'string') {
    return normalizeDescriptionCode(item);
  }

  return normalizeDescriptionCode(
    item.description_code ||
    item.code ||
    item.key ||
    item.document_code ||
    item.current_document_code ||
    item.expected_document_code ||
    item.uploaded_document_code
  );
}

function isAttachmentRequired(item) {
  if (!item || typeof item !== 'object') return false;

  if (item.is_attachment_required !== undefined) {
    return boolValue(item.is_attachment_required);
  }

  if (item.attachment_required !== undefined) {
    return boolValue(item.attachment_required);
  }

  if (item.required !== undefined) {
    return boolValue(item.required);
  }

  if (item.is_required !== undefined) {
    return boolValue(item.is_required);
  }

  if (item.mandatory !== undefined) {
    return boolValue(item.mandatory);
  }

  const requirement = normalizeRequirementType(
    item.document_requirement ||
    item.requirement_type ||
    item.required_document
  );

  if (requirement) {
    return requirement === 'required_document';
  }

  return false;
}

function getRequirement(item) {
  if (!item || typeof item !== 'object') return '';

  if (isAttachmentRequired(item)) return 'required_document';

  const requirement = normalizeRequirementType(
    item.document_requirement ||
    item.requirement_type ||
    item.required_document ||
    item.is_required ||
    item.required ||
    item.mandatory
  );

  return requirement || 'optional_document';
}

function isUploadedOrBackendDone(item) {
  if (!item || typeof item !== 'object') return false;

  const status = String(item.bot_status || item.status || item.upload_status || item.state || '').toLowerCase();

  return (
    item.uploaded === true ||
    item.uploaded === 'true' ||
    item.is_uploaded === true ||
    item.is_uploaded === 'true' ||
    status === 'uploaded' ||
    status === 'approved' ||
    status === 'correction_uploaded'
  );
}

function isRejected(item) {
  if (!item || typeof item !== 'object') return false;

  const status = String(item.bot_status || item.status || '').toLowerCase();
  return status === 'rejected';
}

function isPendingRequiredForUpload(item) {
  return (
    isAttachmentRequired(item) &&
    !isUploadedOrBackendDone(item) &&
    !isRejected(item) &&
    item.upload_later !== true &&
    item.upload_later !== 'true'
  );
}

function isPendingUploadLater(item) {
  return (
    isAttachmentRequired(item) &&
    !isUploadedOrBackendDone(item) &&
    !isRejected(item) &&
    (
      item.upload_later === true ||
      item.upload_later === 'true'
    )
  );
}

function extractExpectedFromReply(text) {
  const s = String(text || '');

  const patterns = [
    /First document required:\s*([^\n\r]+)/i,
    /Please upload:\s*([^\n\r]+)/i,
    /Please upload the required document:\s*([^\n\r]+)/i,
    /upload:\s*([^\n\r]+)/i
  ];

  for (const p of patterns) {
    const m = s.match(p);
    if (m && m[1]) return m[1].trim();
  }

  return '';
}

function getChecklistLists(data) {
  const checklistKeys = [
    'document_checklist',
    'required_documents',
    'pending_required_documents',
    'pending_documents',
    'documents_required',
    'documents',
    'checklist',
    'service_checklist',
    'checklist_lines'
  ];

  const result = [];

  for (const key of checklistKeys) {
    if (Array.isArray(data[key])) {
      result.push({
        key,
        list: data[key]
      });
    }
  }

  return result;
}

function findChecklistItemByCodeOrLabel(data, code, label) {
  const normalizedCode = normalizeDescriptionCode(code);
  const normalizedLabel = String(label || '').trim().toLowerCase();

  const lists = getChecklistLists(data);

  for (const entry of lists) {
    const found = entry.list.find((item) => {
      const itemCode = getCode(item);
      const itemLabel = String(getLabel(item) || '').trim().toLowerCase();

      if (!isAttachmentRequired(item)) return false;
      if (isUploadedOrBackendDone(item)) return false;
      if (isRejected(item)) return false;

      if (normalizedCode && itemCode === normalizedCode) return true;
      if (normalizedLabel && itemLabel === normalizedLabel) return true;

      return false;
    });

    if (found) return found;
  }

  return null;
}

function findFirstPendingChecklistItem(data) {
  const lists = getChecklistLists(data);

  for (const entry of lists) {
    const found = entry.list.find(item => isPendingRequiredForUpload(item));
    if (found) return found;
  }

  for (const entry of lists) {
    const found = entry.list.find(item => isPendingUploadLater(item));
    if (found) return found;
  }

  return null;
}

function updateDocInList(list, uploadedCode, updateValues) {
  if (!Array.isArray(list)) return list;

  return list.map((item) => {
    const code = getCode(item);

    if (code !== uploadedCode) return item;

    if (typeof item === 'string') {
      return {
        label: item,
        code: uploadedCode,
        description_code: uploadedCode,
        ...updateValues
      };
    }

    return {
      ...item,
      code: item.code || uploadedCode,
      description_code: item.description_code || uploadedCode,
      ...updateValues
    };
  });
}

function updateDocInSession(data, uploadedCode, updateValues) {
  const checklistKeys = [
    'document_checklist',
    'required_documents',
    'pending_required_documents',
    'pending_documents',
    'documents_required',
    'documents',
    'checklist',
    'service_checklist',
    'checklist_lines'
  ];

  for (const key of checklistKeys) {
    data[key] = updateDocInList(data[key], uploadedCode, updateValues);
  }
}

function findNextPendingDoc(data) {
