// - Media/document upload should continue to marriage service workflow

const isDocumentCorrectionStage =
  currentStage === 'document_correction_collection' ||
  currentStage === 'document_correction_pending' ||
  currentStage === 'correction_collection' ||
  currentStage === 'correction_pending' ||
  data.current_stage === 'document_correction_collection' ||
  data.current_stage === 'document_correction_pending' ||
  data.current_stage === 'correction_collection' ||
  data.current_stage === 'correction_pending' ||
  isTrue(data.document_correction_required) ||
  isTrue(data.correction_required) ||
  (Array.isArray(data.correction_queue) && data.correction_queue.length > 0);

const mediaUpload = hasIncomingMedia();

if (!reply && isDocumentCorrectionStage) {
  data.current_stage = 'document_correction_collection';
  data.active_service = 'marriage_registration';
  data.document_correction_required = true;
  data.correction_required = true;

  activeService = 'marriage_registration';
  currentStage = 'document_correction_collection';

  if (mediaUpload) {
    shouldCallMarriage = true;
    route = 'marriage_service';

    return [{
      json: {
        customer_id: incoming.customer_id || row.customer_id || data.customer_id || '',
        channel: 'whatsapp',
        whatsapp_phone: incoming.whatsapp_phone || data.whatsapp_phone || '',
        customer_name: incoming.customer_name || data.customer_name || '',
        message: incoming.message,
        incoming_message: msgRaw,
        user_reply: msgRaw,
        message_type: incoming.message_type,
        media: incoming.media,
        session_row_id: row.id || '',
        active_service: 'marriage_registration',
        current_stage: 'document_correction_collection',
        language,
        intent: 'marriage_registration',
        session_data: JSON.stringify(data),
        reply: '',
        output: '',
        last_reply: '',
        updated_at: new Date().toISOString(),
        should_call_marriage_workflow: true,
        should_call_marriage_service: true,
        route
      }
    }];
  }

  reply = correctionUploadReply(language);
  data.last_reply = reply;

  return [{
    json: {
      customer_id: incoming.customer_id || row.customer_id || data.customer_id || '',
      channel: 'whatsapp',
      whatsapp_phone: incoming.whatsapp_phone || data.whatsapp_phone || '',
      customer_name: incoming.customer_name || data.customer_name || '',
      message: incoming.message,
      incoming_message: msgRaw,
      user_reply: msgRaw,
      message_type: incoming.message_type,
      media: incoming.media,
      session_row_id: row.id || '',
      active_service: 'marriage_registration',
      current_stage: 'document_correction_collection',
      language,
      intent: 'marriage_registration',
      session_data: JSON.stringify(data),
      reply,
      output: reply,
      last_reply: reply,
      updated_at: new Date().toISOString(),
      should_call_marriage_workflow: false,
      should_call_marriage_service: false,
      route: 'direct_reply'
    }
  }];
}

// --------------------------------------------------
// 4. Global commands
// --------------------------------------------------

if (['restart', 'reset', 'start'].includes(msg)) {
  data = {};
  language = '';
  activeService = '';
  currentStage = 'language_selection';
}

if (['menu', 'main menu'].includes(msg)) {
  activeService = '';
  currentStage = 'main_menu';
  data.active_service = '';
  data.current_stage = 'main_menu';
  reply = menuByLanguage(language || data.language || 'English');
}

if (msg.includes('change language') || msg === 'language') {
  activeService = '';
  language = '';
  currentStage = 'language_selection';
  data.active_service = '';
  data.current_stage = 'language_selection';
  data.language = '';
  reply = languageMenu();
}

// --------------------------------------------------
// 5. Language selection
// --------------------------------------------------

if (!reply && currentStage === 'language_selection') {
  if (msg === '1') language = 'English';
  else if (msg === '2') language = 'Tamil';
  else if (msg === '3') language = 'Tanglish';
  else {
    reply = languageMenu();
    data.current_stage = 'language_selection';
    data.active_service = '';
  }

  if (!reply) {
    data.language = language;
    data.current_stage = 'main_menu';
    data.active_service = '';
    activeService = '';
    currentStage = 'main_menu';
    reply = menuByLanguage(language);
  }
}

// --------------------------------------------------
// 6. Main menu
// --------------------------------------------------

if (!reply && currentStage === 'main_menu') {
  if (msg === '1') {
    data.main_menu_selected = 'service_status';
    data.current_stage = 'ticket_status_reference';
    data.active_service = '';
    activeService = '';
    currentStage = 'ticket_status_reference';

    reply = language === 'Tamil'
      ? 'உங்கள் சேவை கோரிக்கை எண் அல்லது பதிவு செய்யப்பட்ட மொபைல் எண்ணை பகிரவும்.'
      : language === 'Tanglish'
        ? 'Unga service request number illa registered mobile number share pannunga.'
        : 'Please share your service request number or registered mobile number to check the status.';

  } else if (msg === '2') {
    data.main_menu_selected = 'new_service';
    data.current_stage = 'service_selection';
    data.active_service = '';
    activeService = '';
    currentStage = 'service_selection';
    reply = serviceMenuByLanguage(language || data.language || 'English');

  } else {
    reply = menuByLanguage(language || data.language || 'English');
  }
}

// --------------------------------------------------
// 7. Service selection
// --------------------------------------------------

if (!reply && currentStage === 'service_selection') {
  if (msg === '1' || msg.includes('marriage')) {
    data.main_menu_selected = 'new_service';
    data.active_service = 'marriage_registration';
    data.intent = 'marriage_registration';
    data.current_stage = 'start';
    data.language = language || data.language || 'English';

    activeService = 'marriage_registration';
    currentStage = 'start';
    shouldCallMarriage = true;
    route = 'marriage_service';

  } else {
    reply = serviceMenuByLanguage(language || data.language || 'English');
  }
}

// --------------------------------------------------
// 8. Ticket status placeholder
// --------------------------------------------------

if (!reply && currentStage === 'ticket_status_reference') {
  data.ticket_status_requested = true;
  data.ticket_reference = msgRaw;
  data.current_stage = 'main_menu';

  reply = language === 'Tamil'
    ? 'நன்றி. உங்கள் சேவை நிலையை சரிபார்க்க எங்கள் குழு உதவும். முக்கிய மெனுவுக்கு திரும்புகிறோம்.\n\n' + menuByLanguage(language)
    : language === 'Tanglish'
      ? 'Nandri. Unga service status check panna team help pannuvanga. Main menu ku thirumbi porom.\n\n' + menuByLanguage(language)
      : 'Thank you. Our team will help check your service status. Returning to main menu.\n\n' + menuByLanguage(language);
}

// --------------------------------------------------
// 9. Existing active marriage service path
// --------------------------------------------------

if (!reply && activeService === 'marriage_registration') {
  shouldCallMarriage = true;
  route = 'marriage_service';
}

// --------------------------------------------------
// 10. Fallback
// --------------------------------------------------

if (!reply && !shouldCallMarriage) {
  reply = languageMenu();
  currentStage = 'language_selection';
  activeService = '';
  data.current_stage = 'language_selection';
  data.active_service = '';
}

// --------------------------------------------------
// 11. Save and return
// --------------------------------------------------

data.language = language || data.language || '';
data.current_stage = currentStage;
data.active_service = activeService;

data.whatsapp_phone = incoming.whatsapp_phone;
data.customer_name = incoming.customer_name || data.customer_name || '';

return [{
  json: {
    customer_id: incoming.customer_id || row.customer_id || data.customer_id || '',
    channel: 'whatsapp',
    whatsapp_phone: incoming.whatsapp_phone || data.whatsapp_phone || '',
    customer_name: incoming.customer_name || data.customer_name || '',

    message: incoming.message,
    incoming_message: msgRaw,
    user_reply: msgRaw,

    message_type: incoming.message_type,
    media: incoming.media,
    session_row_id: row.id || '',

    active_service: activeService,
    current_stage: currentStage,
    language: language || data.language || '',
    session_data: JSON.stringify(data),

    reply,
    output: reply,
    last_reply: reply,
    updated_at: new Date().toISOString(),

    should_call_marriage_workflow: shouldCallMarriage,
    should_call_marriage_service: shouldCallMarriage,

    route
  }
}];

const service = $json || {};
const previous = $('CODE_Menu_And_Route_Handler4').first().json || {};

let reply = service.chatbot_reply || service.reply || service.output || service.last_reply || 'Please continue.';
let sessionData = service.session_data || previous.session_data || '{}';
if (typeof sessionData === 'object') sessionData = JSON.stringify(sessionData);

const language = service.language || previous.language || 'English';
const currentStage = service.current_stage || previous.current_stage || 'start';
const activeService = service.active_service || previous.active_service || 'marriage_registration';

return [{
  json: {
    customer_id: previous.customer_id,
    channel: 'whatsapp',
    whatsapp_phone: previous.whatsapp_phone,
    active_service: activeService,
    current_stage: currentStage,
    language,
    session_data: sessionData,
    reply,
    output: reply,
    last_reply: reply,
    updated_at: new Date().toISOString(),
    lead_created: service.lead_created || false,
    lead_reference: service.lead_reference || service.service_request_number || ''
  }
}];
